INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch00-two-pints', '2026-08-14', 'Two Pints and a Map', 'QF1, an upgrade out of Saigon, and a table in Kensington', '[{"t":"map","focus":"london","by":"seed"},{"t":"p","text":"Twenty-six hours out of Saigon the seat turned left instead of right, which we took calmly, the way you take weather, and by six that evening we were at a table off Kensington High Street with two pints and no plan beyond the general direction of Europe.","by":"seed"},{"t":"p","text":"The trip drew itself somewhere in the second pint, the way the good ones do — nobody proposed anything, the map just started talking, and by the time the glasses were empty there was a shape on the table that nineteen days later would turn out to have been roughly right about everything except the parts it was completely wrong about.","by":"seed"},{"t":"doctrine","text":"plans you make argue with you. this one just turned up.","by":"seed"},{"t":"prompt","q":"Which pub, and whose pint was the map drawn on?","by":"seed"},{"t":"prompt","q":"What did the upgrade actually buy — the seat or the sleep?","by":"seed"},{"t":"prompt","q":"What was the first port either of us said out loud?","by":"seed"},{"t":"mono","text":"Marriott Kensington, one night, checked in at nine in the morning like civilised people","by":"seed"},{"t":"card","star":"the seat turned left","lines":[],"by":"seed"}]', '["doctrine","ledger","hardship"]', 'conditions remain grim', 0, 10);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch01-gare-du-nord', '2026-08-15', 'Missed It by a Minute', 'three men, one lanyard, and the 17:56 leaving without us', '[{"t":"map","focus":"paris","by":"seed"},{"t":"p","text":"The 13:31 out of St Pancras did what it always does, which is make France feel like a suburb, and at 16:49 we were at Gare du Nord with eighty kilos of luggage and seventy minutes to cross town for the 17:56 to Lyon.","by":"seed"},{"t":"p","text":"At the métro barriers a man wearing a lanyard explained that he worked there, which he did not, and two colleagues of his arranged themselves behind us, and there followed a short conversation in two languages about whether our tickets and our bags required his assistance, which they did not. Claire was behind me the whole time. The tickets stayed where they were, the three gentlemen went off to find easier company, and we missed the 17:56 by one minute, which is the part I am still filing paperwork about.","by":"seed"},{"t":"prompt","q":"What did the lanyard actually look like?","by":"seed"},{"t":"prompt","q":"What was said to the two behind us, and in which language?","by":"seed"},{"t":"p","text":"The pré-plainte went in online that evening, four attachments, the French state receiving our account with the administrative warmth of a toll booth. The 19:00 took us to Lyon instead — a city neither of us had planned to sleep in, which is the kind of navigational error you would pay money for, and in a sense we had.","by":"seed"},{"t":"ledger","amount":"981 GBP","text":"Eurostar Premier, coach 12, the seats that did their job","by":"seed"},{"t":"ledger","amount":"148 EUR","text":"the 19:00 to Lyon, bought at 18:16, gate still open","by":"seed"},{"t":"ledger","amount":"0 EUR","text":"the pré-plainte, filed online, four attachments","by":"seed"},{"t":"doctrine","text":"avoid ruin, then optimise. lived, that evening, in exactly that order.","by":"seed"},{"t":"prompt","q":"What went into the pré-plainte as evidence?","by":"seed"},{"t":"card","star":"the tickets stayed where they were","lines":[],"by":"seed"}]', '["screens","ledger","hardship"]', 'for a minute there, conditions were grim', 0, 20);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch02-lyon-caught-us', '2026-08-16', 'The City That Caught Us', 'nobody had planned any of this, which is why it worked', '[{"t":"map","focus":"lyon","by":"seed"},{"t":"p","text":"We woke up in a city neither of us had chosen, which is an unusual way to meet one, nothing promised so nothing owed. The hotel used to be the Hôtel Dieu, a hospital from the seventeenth century, and they have kept the bones of it, corridors wide enough for stretchers, a dome built for last rites, and the building now dispenses breakfast instead, same mission of making people feel better, revised pricing.","by":"seed"},{"t":"p","text":"By mid-morning Lyon was baking, properly, the stone handing the heat back with interest, so we retreated into the Halles Paul Bocuse, which is what happens when a city decides its market deserves a roof and its greatest cook''s name over the door, and we laid in provisions with the seriousness of people who had no plan to serve them.","by":"seed"},{"t":"prompt","q":"What came home from Halles Paul Bocuse and what got eaten standing up?","by":"seed"},{"t":"p","text":"Towards evening we took la ficelle up to Fourvière, the funicular, two minutes of gradient the city stopped noticing sometime last century.","by":"seed"},{"t":"drop","text":"The string has been hauling Lyon up its own hill since 1862, and the town is so unimpressed it named it after kitchen twine. What does a city have to see before a hundred and sixty years of not falling counts as showing off?","by":"seed"},{"t":"p","text":"At the top there are terraces with the whole city laid out under them, both rivers, the roofs going pink, and we had a bottle of champagne that was not going to survive another day of that heat, so it had to be dealt with on the spot, and we would like it minuted that we objected. Sunset was 20:46 and it ran on time, which is more than can be said for the service that delivered us here in the first place. Conditions, in short, remained grim.","by":"seed"},{"t":"prompt","q":"What was the champagne on the Fourvière terrace?","by":"seed"},{"t":"doctrine","text":"\"Nobody is required to tell the planned city what the unplanned one did.\"","by":"seed"},{"t":"p","text":"Somewhere between the market and the bottle it was settled that we were not leaving in the morning, although nobody remembers a vote being held.","by":"seed"},{"t":"prompt","q":"Who decided Lyon deserved the second night, and when?","by":"seed"},{"t":"card","star":"A bottle over both rivers at 20:46, in a city that caught us.","lines":[],"by":"seed"}]', '["drops","doctrine","hardship"]', 'the hardship continues', 0, 30);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch03-fourteen-degrees', '2026-08-17', 'Fourteen Degrees in the Caveau', 'Côte-Rôtie, Condrieu, and a mountain we declined to see badly', '[{"t":"map","focus":"lyon","by":"seed"},{"t":"p","text":"We had a driver for the day, which is the correct way to do the northern Rhône, since somebody has to stay sober and it was not going to be either of us. South of Lyon the valley narrows and the vineyards stop pretending to be agriculture, terraces stacked up slopes you would want a rope for in any other context, Côte-Rôtie above Ampuis on one side and Condrieu a few bends further on, the whole arrangement run this way for about two thousand years on the theory that if the hill faces the sun hard enough, the wine will forgive you the labour.","by":"seed"},{"t":"drop","text":"The roasted slope, named by people who stood on it in August and knew exactly what they were describing. Who carried the first stones up?","by":"seed"},{"t":"p","text":"Guigal''s Caveau du Château sits at fourteen degrees, which in a normal year is a technical note about storage and in that particular week made it, by a wide margin, the coolest room in France. Conditions were grim. There is a version of this day where I explain what Viognier does at cellar temperature and a version where I just tell you we went quiet in there, and I am going with the second. We stayed as long as the tasting could reasonably be stretched, then a bit longer, and bottles were involved by the exit.","by":"seed"},{"t":"prompt","q":"Which bottle came back from the Caveau?","by":"seed"},{"t":"ledger","amount":"","text":"— bottles from the Caveau, count unrecorded","by":"seed"},{"t":"p","text":"Mont Blanc had been sitting at the end of the plan the way it sits at the end of every plan in that part of the world, and somewhere in that day it came off the sheet. Not cancelled. Deferred, which in this family is a different word entirely, with its own file.","by":"seed"},{"t":"prompt","q":"Where exactly were we standing when Mont Blanc got deferred?","by":"seed"},{"t":"doctrine","text":"I won''t watch cams… Oppenheimer in 70mm","by":"seed"},{"t":"prompt","q":"What was the 70mm line a reply to?","by":"seed"},{"t":"p","text":"The mountain is not going anywhere, and the driver took us back up the valley into the August, which had not improved.","by":"seed"}]', '["doctrine","drops","ledger"]', 'we press on', 0, 40);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch04-the-1140', '2026-08-18', 'The 11:40 to Nice', 'via Marseille, a seaview at the end of it', '[{"t":"map","focus":"nice","by":"seed"},{"t":"p","text":"The 11:40 went south, which is all we asked of it, and for once the plan and the timetable were the same document. One change at Marseille, a phrase that reads harmlessly enough on a booking confirmation and involves rather more luggage in person, and we made the second train with time to spare, which after Paris felt like showing off.","by":"seed"},{"t":"prompt","q":"What did Marseille look like from the platform?","by":"seed"},{"t":"mono","text":"TKD3G6 / BL4P7Q / HPW6G9 — three references, two trains, zero negotiations at any barrier.","by":"seed"},{"t":"p","text":"Out of Marseille the sea turned up on the right-hand side and stayed there the rest of the way, the whole coast running along beside the train like it had nothing better to do, and nobody charges extra for that yet, though give them time.","by":"seed"},{"t":"p","text":"Hotel Suisse is on Quai Rauba Capeù, which is Niçois rather than French and which nobody needs to pronounce correctly to be let in. The lift was small, the room was not, and when I opened the shutters the entire Baie des Anges was in the window, the full bay, blue out to the horizon, at which point I noted for the record that conditions had deteriorated further and were now frankly unreasonable.","by":"seed"},{"t":"prompt","q":"What could you see when the shutters opened?","by":"seed"},{"t":"ledger","amount":"880 AUD","text":"Hotel Suisse, the seaview, breakfast","by":"seed"},{"t":"p","text":"The seaview was itemised on the invoice, which is correct procedure, hardship at that level should always be receipted, and breakfast was included, so there was no prospect of the situation improving before mid-morning at the earliest.","by":"seed"},{"t":"p","text":"We had come a long way for water and the water had turned up in bulk, on schedule, directly below the window. Somewhere down the hill that evening there was a first dinner in Nice, and that is exactly where the record goes thin.","by":"seed"},{"t":"prompt","q":"First dinner in Nice — where, and who chose?","by":"seed"},{"t":"card","star":"The shutters, and what was behind them.","lines":[],"by":"seed"}]', '["water","ledger","hardship"]', 'no relief in sight', 0, 50);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch05-the-last-berth', '2026-08-19', 'The Last Berth', 'booked Monday, boarded Wednesday, sailed at six', '[{"t":"map","focus":"nice","by":"seed"},{"t":"p","text":"The last morning ashore went to the beach, where Claire progressed the tan and I conducted a full review of the sand, which was ordinary sand, doing ordinary sand things, in front of water that had no business being that colour, and conditions overall remained grim, sun, salt, nothing required of anyone until four.","by":"seed"},{"t":"p","text":"The ship had been booked two days out, on one of the last berths going, which is not the recommended run-up to ten nights at sea and is exactly the run-up we used. Two days is roughly the window between finding out a thing exists and watching somebody else get it, and we have run that analysis before, so the decision took about as long as it deserved to.","by":"seed"},{"t":"doctrine","text":"\"When the right asset shows up late, the answer is still yes.\"","by":"seed"},{"t":"ledger","amount":"23,280 AUD","text":"the ship, ten nights, all of it","by":"seed"},{"t":"mono","text":"Le Dumont d''Urville · boarding 16:00 · sail 18:00 · Cabin 306, Deck 3","by":"seed"},{"t":"p","text":"At 16:00 we boarded Le Dumont d''Urville, 184 passengers, 92 staterooms, 118 crew, which works out to better than one crew member for every two of us, a ratio I checked twice and elected not to argue with. Cabin 306, Deck 3, which put the balcony close enough to the water that the water stopped being a view and became a fitting of the room, part of the joinery, present at all hours.","by":"seed"},{"t":"prompt","q":"When did we know 306 was the right cabin?","by":"seed"},{"t":"ledger","amount":"400 EUR","text":"Virtuoso credit, to be spent aboard, fate unrecorded","by":"seed"},{"t":"prompt","q":"What did the €400 Virtuoso credit become?","by":"seed"},{"t":"p","text":"She sailed at 18:00 and Nice went off the stern slowly, the beach we had audited that morning included, and the arithmetic of it was pleasing, morning on the sand, evening at sea, nothing owed anywhere in between. Ten nights of this lay ahead, and I want it recorded that we faced them without complaint.","by":"seed"},{"t":"prompt","q":"Where were we standing when she sailed?","by":"seed"},{"t":"card","star":"Nice off the stern from the balcony of 306","lines":[],"by":"seed"}]', '["ledger","doctrine","hardship"]', 'morale remains low', 0, 60);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch06-calvi', '2026-08-20', 'The Citadel from the Water', 'first tender, first walking tour, Nelson''s worst day', '[{"t":"map","focus":"calvi","by":"seed"},{"t":"p","text":"Calvi was the first tender of the trip, tendering being the system where the ship anchors off, everyone files down to sea level, and you go ashore in a boat the size of a bus, and the whole arrangement exists mainly so the citadel can do its trick, which is come up out of the water walls-first and keep coming until it has filled every window on the boat. Whoever put those walls there wanted them judged from exactly where we were sitting, and I can report the judging went well.","by":"seed"},{"t":"prompt","q":"What did Claire photograph from the tender?","by":"seed"},{"t":"p","text":"Ashore, the included walking tour, included in the sense that we had already paid for it and were therefore going, and a guide took us up into the citadel on cobbles worn somewhere past marble, under a sun that was also included at no additional cost. Conditions, in short, remained grim, and we soldiered up through the gateways with the rest of the tender, single file where the walls insisted on it.","by":"seed"},{"t":"prompt","q":"What did the guide say that survived the day?","by":"seed"},{"t":"drop","text":"Nelson lost the sight of his right eye besieging these walls in 1794. We had the same walls in front of us and both eyes working, so what would he have called a fair price for the view?","by":"seed"},{"t":"p","text":"Below the ramparts the water was doing what Corsican water is contracted to do, which raised the only real question of the afternoon.","by":"seed"},{"t":"p","text":"The fork in the day was the Revellata snorkel, €150 a head and optional, and €150 a head is the point where optional stops being a word and becomes a position, because on one side of the fork was the clearest water of the itinerary with a guide in it, and on the other was the same water, admired from land, at no charge, and the case for each side was heard in full, on cobbles, in the sun.","by":"seed"},{"t":"mono","text":"Revellata snorkel, optional, EUR 150 pp, resolution not recorded","by":"seed"},{"t":"prompt","q":"Snorkel taken or declined, and on what grounds?","by":"seed"},{"t":"card","star":"Walls first out of the water, both eyes still ours","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'still no rescue', 0, 70);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch07-cap-corse', '2026-08-21', 'Around Cap Corse', 'the gulf, the cap, the wine nobody planned', '[{"t":"map","focus":"saint-florent","by":"seed"},{"t":"p","text":"Saint-Florent was the day the paperwork ran out, no connections to defend, no barriers to hold, nobody in a lanyard as far as the eye could see, just the town around its little port and the gulf lying there all morning entirely unsupervised. Conditions in the gulf remained grim.","by":"seed"},{"t":"prompt","q":"What colour was the gulf, honestly?","by":"seed"},{"t":"drop","text":"Cap Corse is the island''s finger pointed at Genoa, and Genoa has had several hundred years to think about why.","by":"seed"},{"t":"p","text":"The run around the cap was villages, then water, then villages, each one folded into its own slot of coast as if the last one hadn''t happened, and we endured this for the better part of a day with nothing to show for it but the day.","by":"seed"},{"t":"prompt","q":"What was the best thing on Cap Corse nobody had planned?","by":"seed"},{"t":"prompt","q":"Did a Patrimonio glass happen, and where?","by":"seed"},{"t":"card","star":"the gulf, on attendance alone","lines":[],"by":"seed"}]', '["water","drops","hardship"]', 'rations holding', 0, 80);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch08-three-hundred-days', '2026-08-22', 'Three Hundred Days', 'the emperor''s villa, included', '[{"t":"map","focus":"portoferraio","by":"seed"},{"t":"mono","text":"shore excursion — included — Napoleon''s villa, Portoferraio","by":"seed"},{"t":"p","text":"Portoferraio has been catching people who didn''t entirely choose it since 1814, and it caught us in the same spirit, a horseshoe of a harbour with the old town stacked up behind it in the standard Italian arrangement of laundry and geraniums, and above the lot of it the villa, because when a town has had exactly one famous resident it does not waste him.","by":"seed"},{"t":"p","text":"The included excursion went up the hill, and the first thing the villa does is fail to be big enough, which is the whole exhibit really, the man had been running a continent the previous spring and here was a house you could walk end to end in the time it takes to lose a tour group, gardens included, with a terrace from which he could inspect his entire jurisdiction without binoculars.","by":"seed"},{"t":"p","text":"We did the rooms at the pace the group allowed, which is the pace of the slowest photographer, and the rooms held their own, small windows, sea light, furniture built for a man planning to be elsewhere.","by":"seed"},{"t":"prompt","q":"Which object in the villa did we both stop at?","by":"seed"},{"t":"p","text":"He kept the full ceremony going while he was here, the household, the receptions, the etiquette of the Tuileries transplanted onto an audience of one small island, which reads either as dignity or as a man declining to update his org chart.","by":"seed"},{"t":"prompt","q":"What did the guide skip that the book wouldn''t have?","by":"seed"},{"t":"drop","text":"Three hundred days. He rebuilt the roads, reorganised the iron mines and drafted a constitution in that time, on an island he could see the whole of from his terrace, so what would we get done with three hundred days and no meetings?","by":"seed"},{"t":"drop","text":"He gave the island a flag before he gave it anything else, white with a red stripe and three golden bees. What does a man fix on day one, and what does that tell you?","by":"seed"},{"t":"doctrine","text":"\"Deferral is fine. Deferral without a rebooking date is Elba.\"","by":"seed"},{"t":"drop","text":"26 February 1815, out of this exact harbour, back towards the whole catastrophe, entirely of his own accord. How long had he been watching the water?","by":"seed"},{"t":"p","text":"The afternoon was ours once the villa was done, and Elba in the afternoon is the kind of hardship it would be indelicate to describe to people back home.","by":"seed"},{"t":"prompt","q":"Did we swim on Elba, and where?","by":"seed"},{"t":"p","text":"We sailed the same evening, an exit it took him three hundred days to organise.","by":"seed"}]', '["drops","doctrine","hardship"]', 'no word from Paris', 0, 90);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch09-arrival-by-water', '2026-08-23', 'Arrival by Water', 'a private boat, Santa Margherita, Rapallo, the kayak question', '[{"t":"map","focus":"portofino","by":"seed"},{"t":"p","text":"The boat day was the included one, which is the sort of clause you skim at the booking stage and then a launch turns up and the clause means exactly what it said. Santa Margherita, Rapallo, Portofino, the whole run from the water, which is the side that coast was drawn from in the first place.","by":"seed"},{"t":"mono","text":"launch: included. the only line of the week with nothing in the amount column, a category of transaction I don''t fully trust.","by":"seed"},{"t":"p","text":"There was one open item on the day, the kayak, a hundred and ten a head to move under your own power across water we were already being carried over in comfort, which is either the best money on the coast or the silliest, and I could argue both sides.","by":"seed"},{"t":"ledger","amount":"110 EUR pp","text":"the kayak question, resolution unrecorded.","by":"seed"},{"t":"prompt","q":"Kayak — taken or declined, and on what grounds?","by":"seed"},{"t":"p","text":"Santa Margherita and Rapallo split the middle of the day, an hour ashore between them and the record silent on how it was divided.","by":"seed"},{"t":"prompt","q":"Santa Margherita or Rapallo: which got the hour?","by":"seed"},{"t":"p","text":"We had been arriving at places off the water all trip, one way and another, and this was the first day built around nothing else. Portofino came at the end of the run, which is the right end for it. By road it is a queue behind a bus on a lane cut for carts. By sea the harbour simply opens, and the houses stand around it with their good paint facing out, because nobody who built that place expected you to come any other way. We came in the front door.","by":"seed"},{"t":"prompt","q":"What did Portofino look like from the water on the way in?","by":"seed"},{"t":"drop","text":"Every house on that coast keeps its best paint on the seaward wall. Who were they dressed for, before the ferries?","by":"seed"},{"t":"p","text":"It was, all told, a difficult day on the water, and somebody had to have it.","by":"seed"}]', '["water","ledger","drops"]', 'somehow we endure', 0, 100);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch10-the-lily', '2026-08-24', 'The Lily', 'granita in the port, the Giannutri question', '[{"t":"map","focus":"giglio","by":"seed"},{"t":"p","text":"Giglio does its mornings at the port, which is a curve of coloured houses arranged around the boats and not much else, and we did ours there too, on the theory that an island that size has already decided where you will be standing and there is no point arguing with it.","by":"seed"},{"t":"p","text":"There was a granita, which is the one hard fact the morning left behind, and the rest of the detail has gone wherever mornings go.","by":"seed"},{"t":"prompt","q":"Where was the granita and what flavour?","by":"seed"},{"t":"p","text":"Giannutri sat out there the whole time as the open question, a smaller island an hour off the bow, and we had done the deciding about it in advance, which is to say we had decided how we would decide and then declined to reopen the file, per the rules.","by":"seed"},{"t":"doctrine","text":"\"Rule 5: the switch criterion is decided at the fork, once.\"","by":"seed"},{"t":"prompt","q":"Did the Giannutri boat happen?","by":"seed"},{"t":"p","text":"Either way, the water off Giglio Porto runs past Le Scole, a low line of rocks just south of the harbour mouth, and every boat that comes or goes passes them.","by":"seed"},{"t":"drop","text":"Le Scole is where the Costa Concordia went onto the rocks on the night of 13 January 2012. Thirty-two people died, and taking the ship off the island afterwards became the largest maritime salvage in history.","by":"seed"},{"t":"prompt","q":"What was said, if anything, passing Le Scole?","by":"seed"},{"t":"p","text":"The rocks are just rocks again now, and the water over them is the same water as everywhere else on that coast, which is the island''s answer to the whole business and probably the right one.","by":"seed"},{"t":"p","text":"They call Giglio the lily, though apparently the name comes from an old Greek word to do with goats rather than the flower, and the island has clearly decided not to pursue the matter, which by mid-morning struck us as sound policy.","by":"seed"},{"t":"card","star":"granita at the port, flavour under investigation","lines":[],"by":"seed"}]', '["water","drops","doctrine"]', 'the hardship continues', 0, 110);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch11-where-the-painter-stopped', '2026-08-25', 'Where the Painter Stopped', 'the Spanish built the forts; a painter died running past them', '[{"t":"map","focus":"porto-ercole","by":"seed"},{"t":"p","text":"Porto Ercole is one small harbour wearing three Spanish forts, which is a lot of masonry per fishing boat, and tells you what the Spaniards thought of their neighbours back when they ran this coast as the Presidi. The forts stand over the town at exactly the angle their engineers chose to discourage visitors, and we went up anyway, since discouraging visitors is all they do for a living now.","by":"seed"},{"t":"prompt","q":"Which fort got climbed and which got skipped?","by":"seed"},{"t":"p","text":"Below all that defence the water carried on in the usual Argentario manner, a blue that makes the hardship reporting difficult to file with a straight face, and there was a beach involved, which is the whole problem with this stretch of Italy.","by":"seed"},{"t":"prompt","q":"Any swim, or was the beach the view?","by":"seed"},{"t":"doctrine","text":"Conditions remain grim.","by":"seed"},{"t":"p","text":"Somewhere in the middle of the day there was lunch, because there always is, though the paperwork on it is thin.","by":"seed"},{"t":"prompt","q":"What was lunch and who found it?","by":"seed"},{"t":"p","text":"The reason Porto Ercole is in this book at all is that this is where Caravaggio stopped. July 1610, the pardon finally arranged, and the pardon and the paintings both on a felucca that had sailed without him, so he chased it, up this coast, on foot, in that month, in that heat. He was thirty-eight. He got exactly as far as Porto Ercole, and on the 18th of July he was done, which the felucca does not appear to have noticed.","by":"seed"},{"t":"drop","text":"A man running out of coastline, the boat holding its line. Was he chasing the paintings or the pardon?","by":"seed"},{"t":"p","text":"So the town kept the grave, and it is up there somewhere still, filed under a name nobody could spell. The paintings kept the water. That part of the story was not finished at Porto Ercole, and neither are we with it.","by":"seed"},{"t":"card","star":"Porto Ercole, the town that stopped Caravaggio","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'no improvement to report', 0, 120);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch12-at-sea', '2026-08-26', 'At Sea', 'no port, no plan, a volcano possibly at dinner', '[{"t":"map","focus":"porto-ercole--lipari","by":"seed"},{"t":"p","text":"We sailed out of Porto Ercole overnight and woke to the first day of the whole run with no port on it, no tender times, no meeting point, no man with a clipboard, just water in every direction and the day standing there empty, asking what I intended to do about it.","by":"seed"},{"t":"p","text":"So the ship stopped being the thing that carried us between places and became the place itself, the same decks in the same rotation, the sea going past at a speed nobody could verify, no plan to execute and no way to fall behind one, which for a man who runs on a schedule was a set of conditions I can only describe as grim.","by":"seed"},{"t":"drop","text":"The wake was the only evidence we were getting anywhere. How fast does a ship need to go before you stop checking?","by":"seed"},{"t":"prompt","q":"What actually filled the hours between breakfast and the horizon watch?","by":"seed"},{"t":"p","text":"Somewhere in the middle of all that nothing it occurred to me that this was the last piece of pure infrastructure on the whole trip, steel and timetables and staff whose lanyards mean what they say, because from Sicily on the thing was being handed over to people, and people, unlike ships, do not publish schedules.","by":"seed"},{"t":"doctrine","text":"\"The pause is part of the plan.\"","by":"seed"},{"t":"p","text":"A day with nothing in it still gets a card in this family, and Claire''s card is hers to write, so I kept my speculation to myself, which is not the same as not having any.","by":"seed"},{"t":"prompt","q":"What was Claire''s star for the sea day?","by":"seed"},{"t":"p","text":"By evening we were at the rail for the horizon watch, the Aeolians somewhere ahead in the dark, and off to the south there may have been a thin line of smoke standing up off the water where Stromboli keeps its fire going, or it may have been cloud doing a reasonable impression of one, the light was going and I have declined to rule on it.","by":"seed"},{"t":"drop","text":"A mountain that has been burning since before there were countries, filed by the shipping lanes under navigation aids. What else out there works that hard to be taken for granted?","by":"seed"},{"t":"prompt","q":"Did Stromboli smoke?","by":"seed"}]', '["doctrine","drops","hardship"]', 'we soldier on', 0, 130);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch13-obsidian', '2026-08-27', 'Obsidian', 'the Aeolians, up close', '[{"t":"map","focus":"lipari","by":"seed"},{"t":"p","text":"Lipari is the big one, which in the Aeolians is a relative term, and the day began in the port because on Lipari everything does, the island being arranged around its harbour the way an office is arranged around the kettle.","by":"seed"},{"t":"p","text":"The town runs between two harbours with a castle rock in the middle, which is where you put a castle when six thousand years of neighbours keep arriving by boat.","by":"seed"},{"t":"prompt","q":"How did we get around the island — and what did it cost, agreed when?","by":"seed"},{"t":"drop","text":"For about four thousand years the sharpest edge in the known world came off this island, and half the Neolithic Mediterranean carried a flake of Lipari black in its kit. Silicon Valley, same margins, better weather.","by":"seed"},{"t":"p","text":"The north end is pumice country, whole hillsides quarried and shipped by the sack until UNESCO suggested they stop selling the scenery, and the water below the old workings sits over a white seabed that makes the colour the brochures are always lying about, except here.","by":"seed"},{"t":"drop","text":"Pumice is the stone that floats. They dug up a mountain here light enough to swim home.","by":"seed"},{"t":"prompt","q":"Where was lunch, and what story did the table produce?","by":"seed"},{"t":"p","text":"The afternoon belonged to the water, which was the standing arrangement on this leg and was not renegotiated.","by":"seed"},{"t":"prompt","q":"Did anyone jump off anything?","by":"seed"},{"t":"drop","text":"Homer put Aeolus on these islands, handing Odysseus every bad wind tied up in one bag, and the crew opened it within sight of Ithaca. Who opens the bag in this family?","by":"seed"},{"t":"p","text":"By evening the harbour had refilled and the volcanoes were still queueing along the horizon, and I regret to report conditions had not improved.","by":"seed"},{"t":"card","star":"the water, again, which keeps winning these","lines":[],"by":"seed"}]', '["drops","water","ledger"]', 'no end in sight', 0, 140);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch14-the-volcano-upstage', '2026-08-28', 'The Volcano Upstage', 'Giardini Naxos in, granita at Bam Bar, the last night at sea', '[{"t":"map","focus":"taormina","by":"seed"},{"t":"p","text":"The tender put us in at Giardini Naxos, where the Greeks first landed in Sicily two and a half thousand years before us, so the anchorage at least came recommended, and from there the only direction on offer is up, Taormina having been built on a shelf of hill with a clear view of everything and a clear intention of not being easily visited, an intention we overruled.","by":"seed"},{"t":"p","text":"The theatre is what the climb is for. The Greeks cut it into the ridge and pointed the stage straight at Etna, which is to say they looked at the largest volcano in Europe, decided it could act, and wrote it into the show, and it is still in the cast, still on the bill, and by all accounts has never missed a performance. I would also note, for the benefit of certain members of the touring party, that the venue contains no screens, never has, and sold out for centuries regardless.","by":"seed"},{"t":"prompt","q":"Was Etna doing anything behind the stage?","by":"seed"},{"t":"drop","text":"They built the seats before they hired the actors, and aimed the whole thing at the scenery. What else were they pointing their buildings at?","by":"seed"},{"t":"p","text":"Down in the town the true institution is not the theatre, it is Bam Bar, which does granita and has correctly concluded that nothing further is required of it, and you don''t need to read a review because the queue is the review, published daily on the footpath and rigorously refereed. We joined it, on the grounds that conditions were grim and only granita was going to address them.","by":"seed"},{"t":"prompt","q":"What granita, in what order?","by":"seed"},{"t":"card","star":"Bam Bar, where the queue wrote the review and the granita signed it.","lines":[],"by":"seed"},{"t":"p","text":"That was the last night on board.","by":"seed"},{"t":"prompt","q":"What was the last-night table like?","by":"seed"}]', '["drops","screens","hardship"]', 'grim, as forecast', 0, 150);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch15-the-knights-city', '2026-08-29', 'The Knights'' City', 'disembark 08:00; the only painting he ever signed', '[{"t":"map","focus":"valletta","by":"seed"},{"t":"p","text":"We came off the ship at 08:00 into a city built by an order of knights with a great deal of money and a grudge, and the first thing Valletta does is go uphill, which after ten nights of lifts and buffets the party received as a provocation. The Knights put the place up in a hurry after nearly losing the whole island, and it shows, in that everything is a fortress, including a fair proportion of the churches, and the streets run straight down to the harbour so the sea can see exactly what it is dealing with.","by":"seed"},{"t":"p","text":"We had been following Caravaggio around the Mediterranean like creditors, and Valletta is where the trail ends, because the Oratory of St John''s holds the Beheading, the biggest thing he ever painted and the only one he ever signed.","by":"seed"},{"t":"drop","text":"The signature is in the blood running from the Baptist''s throat, f. Michelangelo, the one time in his life he put his name to a canvas. What does a man mean by signing there?","by":"seed"},{"t":"p","text":"I was not ready for it.","by":"seed"},{"t":"prompt","q":"How long did we stand in front of the Beheading?","by":"seed"},{"t":"p","text":"Above the harbour the Saluting Battery fires its gun at twelve whether you have arrived or not, and the sound goes around the Grand Harbour and comes back with interest, which the harbour has been tolerating since the Knights ran the place.","by":"seed"},{"t":"drop","text":"A cannon that exists so ships could set their chronometers by it. Who still sets anything by a cannon?","by":"seed"},{"t":"prompt","q":"Did we make the noon gun or hear it from somewhere else?","by":"seed"},{"t":"p","text":"The 1926 had a premium suite with our name on it and breakfast attached, which after ten nights in a cabin was ruled adequate compensation for the hills, though the ruling was not unanimous until the door actually opened.","by":"seed"},{"t":"mono","text":"1926 La Galerie Art Suites — conf 73521701309804","by":"seed"},{"t":"ledger","amount":"450 AUD","text":"the 1926, premium suite, breakfast","by":"seed"},{"t":"prompt","q":"What was the room like after ten nights afloat?","by":"seed"},{"t":"p","text":"Conditions ashore, it was agreed, remained grim.","by":"seed"}]', '["drops","ledger","hardship"]', 'the siege continues', 0, 160);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch16-slow-malta', '2026-08-30', 'Slow Malta', 'Mdina says nothing; St Peter''s Pool asks one question', '[{"t":"map","focus":"valletta","by":"seed"},{"t":"p","text":"Mdina bills itself as the Silent City, which is the sort of claim I normally like to audit, and I can report it held up. A walled town on a hill that stopped mattering around 1565 and has spent the centuries since declining to comment, streets a horse-width across, limestone the colour of the hour, doors with knockers above eye level for people who no longer answer them. Every other place on this trip had spent the day explaining itself at us, and here was a whole city with nothing to add, which was the point, so we walked it at the pace it asked for and did not add anything either.","by":"seed"},{"t":"prompt","q":"What did Mdina sound like?","by":"seed"},{"t":"p","text":"Back down at the Grand Harbour we crossed to the Three Cities by dghajsa, which is what happens when a gondola gets a proper job, and you sit at water level in a painted boat on a channel that has been moving somebody''s cargo since before the Phoenicians invented the receipt. The Knights ran their fleet out of these creeks, the Royal Navy ran theirs, and now the same water carries tourists at the same unhurried angle, which as career changes go is not the worst.","by":"seed"},{"t":"prompt","q":"What did the dghajsa boatman talk about?","by":"seed"},{"t":"drop","text":"Maltese is the last living branch of Siculo-Arabic, and the most Catholic country in Europe says its prayers to Alla. What does a language keep that its speakers have agreed not to mention?","by":"seed"},{"t":"p","text":"Then out along the coast to St Peter''s Pool, which is not a pool so much as a shelf of pale rock the sea has cut into the shape of a decision. Flat stone, clear water, a drop of a few metres, and the place asks everyone who walks out onto the edge exactly one question. It is a very old question and the rock is completely neutral on it, having watched people answer it both ways for as long as there have been feet. We stood there a while with the water doing its colours below us.","by":"seed"},{"t":"prompt","q":"Did anyone jump at St Peter''s Pool?","by":"seed"},{"t":"card","star":"the dghajsa across the Grand Harbour, sitting at water level in a boat older than the idea of hurrying","lines":[],"by":"seed"}]', '["water","drops","trade-channel"]', 'conditions remain grim', 0, 170);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch17-the-crossing', '2026-08-31', 'The Crossing', 'the biggest fast cat in the Med, then 230 kilometres of Sicily', '[{"t":"map","focus":"pozzallo","by":"seed"},{"t":"p","text":"The St John Paul II left Valletta at 07:30, and Virtu are firm on the point that she is the largest high-speed catamaran in the Mediterranean, which is the sort of fact a boat leads with when it would rather you thought about size than movement. An hour and three quarters of open water between Malta and Sicily, most of it before nine in the morning, and Pozzallo at 09:15, which as ports go is less a destination than a thing ferries admit to on the way past.","by":"seed"},{"t":"mono","text":"Virtu Ferries, St John Paul II, 07:30 Valletta–Pozzallo, ref 10729224","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the ferry pair, two seats on the largest high-speed catamaran in the Med","by":"seed"},{"t":"prompt","q":"Was the crossing smooth, and did anyone regret breakfast?","by":"seed"},{"t":"p","text":"The land side had gone to the trade channel, one car, one driver, 230 kilometres from the bottom-right corner of the island to the top-left of it, and the quotes came back between €280 and €380, which is a hundred euros of daylight on the same road with the same amount of Sicily in the middle of it.","by":"seed"},{"t":"prompt","q":"Which driver quote won, and how was it found?","by":"seed"},{"t":"ledger","amount":"280-380 EUR","text":"the driver, quote range, winner unrecorded","by":"seed"},{"t":"p","text":"Whoever won carried us through the interior, which is the part of the island the postcards skip, the wheat and the distance and the towns that sit up on their hills and watch the road go by without much interest, and by early afternoon we were at Villa Igiea, having started the day in one country and finished the drive in another with a sea in between and no airport involved, which is the correct way to do it and almost never the way it gets done.","by":"seed"},{"t":"drop","text":"Two seas in one day, the one crossed and the one arrived beside. Did anyone clock the moment the water changed sides?","by":"seed"},{"t":"prompt","q":"What was the 230 kilometres like from the back seat?","by":"seed"},{"t":"card","star":"230 kilometres of interior Sicily survived from the back seat","lines":[],"by":"seed"},{"t":"p","text":"Aurora''s train got in from Rome that night, she''d sat an exam that morning, and Palermo could wait an evening.","by":"seed"}]', '["trade-channel","ledger","water"]', 'the hardship continues', 0, 180);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch18-lunch-at-one', '2026-09-01', 'Lunch at One', 'her city, her table, possibly her parents', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"mono","text":"01 SEP · PALERMO · LUNCH 13:00 — no ref, no confirmation email, no cancellation policy","by":"seed"},{"t":"p","text":"By the first of September the trip was a folder of PDFs, flights, rooms, transfers, every line with its reference number and its cancellation window, and then one line with nothing on it at all, lunch, Palermo, one o''clock or thereabouts, and the line with nothing on it was the one the whole day was built around. It never appeared on any platform, no card ever held it, it moved through the trade channel or it did not move at all, and the trade channel had delivered.","by":"seed"},{"t":"doctrine","text":"\"You can book a table anywhere in the world. You can''t book being taken to one.\"","by":"seed"},{"t":"p","text":"Aurora picked the place, which settled the question of where to eat in Palermo the way it should always be settled, a local choosing the room being the last screen you ever need, and we asked for no further details and were given none.","by":"seed"},{"t":"prompt","q":"Where did she take us?","by":"seed"},{"t":"p","text":"The register said possibly her parents, which is the kind of possibly you iron a shirt for, and on that subject the paperwork stayed silent.","by":"seed"},{"t":"prompt","q":"Were the parents there — and what was that like?","by":"seed"},{"t":"p","text":"What the bookings could tell me was the shape of the thing, a table filled at one, Sicily, September, conditions presumably grim, the afternoon cancelled in advance with nothing scheduled against it, which cost me more discipline than it cost Claire. Past that point the record goes quiet at one o''clock and does not pick up again until somewhere well into the afternoon, which is how you know it was a proper table.","by":"seed"},{"t":"prompt","q":"Which dish did the table go quiet for?","by":"seed"},{"t":"p","text":"Nothing to confirm, nothing to cancel, nothing to claim back. The best-performing asset on the itinerary and it never touched the ledger.","by":"seed"},{"t":"ledger","amount":"0.00 EUR","text":"a table at one, the only line on the trip money couldn''t reach","by":"seed"},{"t":"drop","text":"One line in the folder with no reference number on it. How many of those does a trip need before it counts as a good one?","by":"seed"},{"t":"card","star":"Lunch at one, her room, her call.","lines":[],"by":"seed"}]', '["trade-channel","screens","hardship"]', 'conditions remain grim', 0, 190);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch19-gold-in-the-morning', '2026-09-02', 'Gold in the Morning', 'mosaics before the heat, Ballarò before lunch, the pool before the last dinner', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"p","text":"Wednesday we went up the hill to Monreale before the heat had properly reported for duty, which is the only hour that town receives visitors on fair terms, and stood in the cathedral William II ran up in the 1170s largely to annoy the Archbishop of Palermo, acres of gold mosaic depending on whose survey you trust, every surface employed, and you come in out of the white glare of the square and the whole ceiling switches itself on above you like a ledger that only ever recorded credits.","by":"seed"},{"t":"drop","text":"Somewhere in the nave William is handing the finished church up to the Virgin, holding the entire building in his two hands like a model. What would you build, at twenty-two, if nobody could stop you?","by":"seed"},{"t":"prompt","q":"What did Claire say inside Monreale?","by":"seed"},{"t":"p","text":"Then back down into Palermo and into Ballarò, which by mid-morning was at full voice, which is the market''s only setting, and we let it carry us through on the theory that the last morning is the one where you finally buy the things you have been circling all week.","by":"seed"},{"t":"prompt","q":"What came home from Ballarò?","by":"seed"},{"t":"p","text":"The afternoon was assigned to the Villa Igiea pool and I want it minuted that we endured it, the water holding its temperature without apology, the sea lying flat on the other side of the balustrade doing nothing to help, and hour after hour we bore it, because nobody packed so much as a sock, the flight not being until Thursday midday, and a bag half-zipped on a Wednesday is a sign of weakness.","by":"seed"},{"t":"p","text":"Conditions, in short, remained grim to the end.","by":"seed"},{"t":"p","text":"There was one last dinner, the grand kind, the sort Sicily had been auditioning for all fortnight, and it went long, as the last one is contractually required to.","by":"seed"},{"t":"prompt","q":"Where was the last dinner, and what was the toast?","by":"seed"},{"t":"card","star":"Proposed: the gold, obviously, though the pool put up a late and unwelcome case.","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'the ordeal nears its end', 0, 200);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch20-the-long-way-home', '2026-09-03', 'The Long Way Home', 'BA619, a lounge, QF2, Saturday morning somewhere', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"p","text":"This one I wrote off the confirmation emails on the third of September, which makes it the only chapter where nothing had gone wrong yet, and I would like that noted for the file. The paperwork said BA619 out of Palermo at 12:05, Heathrow at 14:20, and then six and a half hours of Terminal 3 to get through before QF2 at 20:50, the bulk of it to be served in the First lounge, where conditions are historically grim.","by":"seed"},{"t":"mono","text":"BA619 PMO–LHR 12:05 → 14:20 · QF2 LHR–SYD dep 20:50 · Premium Flex","by":"seed"},{"t":"p","text":"QF2 had been the Wednesday until it wasn''t, which is what Premium Flex is for, you buy the fare knowing the plan is going to move and then you let it move, and the only piece still in the air when I wrote this was the bid for the front cabin, sitting in a Qantas machine somewhere marked pending, and pending is where this chapter has to leave it.","by":"seed"},{"t":"prompt","q":"Did the F bid land?","by":"seed"},{"t":"p","text":"An afternoon is a long tenancy in a lounge, even that one, and I had it pencilled in as the trip''s last stretch of proper hardship, six hours of other people''s hospitality between us and the gate, and none of what actually happened in there made it into any email.","by":"seed"},{"t":"prompt","q":"What was the lounge''s one contribution to the trip?","by":"seed"},{"t":"p","text":"The bookings ended the way bookings always do, cleanly, no weather, no lanyards, no one-minute margins, QF2 down in Sydney on the Saturday morning with the whole thing behind us, and that is where the paperwork stops.","by":"seed"},{"t":"prompt","q":"First thing said on the ground in Sydney?","by":"seed"},{"t":"p","text":"Which leaves the books, because somebody in this family was always going to keep them.","by":"seed"},{"t":"ledger","amount":"981 GBP","text":"Eurostar, the 13:31 out of St Pancras","by":"seed"},{"t":"ledger","amount":"148 EUR","text":"the 19:00 to Lyon, bought at 18:16","by":"seed"},{"t":"ledger","amount":"880 AUD","text":"Hotel Suisse","by":"seed"},{"t":"ledger","amount":"23,280 AUD","text":"the ship","by":"seed"},{"t":"ledger","amount":"450 AUD","text":"the 1926","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the ferry pair","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the driver","by":"seed"},{"t":"doctrine","text":"The plan is a doctrine, not an itinerary; the best assets can''t be booked, only introduced.","by":"seed"}]', '["ledger","doctrine","hardship"]', 'the hardship continues, now at altitude', 0, 210);
INSERT OR IGNORE INTO journal_meta (id, json) VALUES ('prompts', '{"ch00-two-pints":["Which pub, and whose pint was the map drawn on?","What did the upgrade actually buy — the seat or the sleep?","What was the first port either of us said out loud?"],"ch01-gare-du-nord":["What did the lanyard actually look like?","What was said to the two behind us, and in which language?","What went into the pré-plainte as evidence?"],"ch02-lyon-caught-us":["What came home from Halles Paul Bocuse and what got eaten standing up?","What was the champagne on the Fourvière terrace?","Who decided Lyon deserved the second night, and when?"],"ch03-fourteen-degrees":["Which bottle came back from the Caveau?","Where exactly were we standing when Mont Blanc got deferred?","What was the 70mm line a reply to?"],"ch04-the-1140":["What did Marseille look like from the platform?","What could you see when the shutters opened?","First dinner in Nice — where, and who chose?"],"ch05-the-last-berth":["When did we know 306 was the right cabin?","What did the €400 Virtuoso credit become?","Where were we standing when she sailed?"],"ch06-calvi":["What did Claire photograph from the tender?","What did the guide say that survived the day?","Snorkel taken or declined, and on what grounds?"],"ch07-cap-corse":["What colour was the gulf, honestly?","What was the best thing on Cap Corse nobody had planned?","Did a Patrimonio glass happen, and where?"],"ch08-three-hundred-days":["Which object in the villa did we both stop at?","What did the guide skip that the book wouldn''t have?","Did we swim on Elba, and where?"],"ch09-arrival-by-water":["Kayak — taken or declined, and on what grounds?","Santa Margherita or Rapallo: which got the hour?","What did Portofino look like from the water on the way in?"],"ch10-the-lily":["Where was the granita and what flavour?","Did the Giannutri boat happen?","What was said, if anything, passing Le Scole?"],"ch11-where-the-painter-stopped":["Which fort got climbed and which got skipped?","Any swim, or was the beach the view?","What was lunch and who found it?"],"ch12-at-sea":["What actually filled the hours between breakfast and the horizon watch?","What was Claire''s star for the sea day?","Did Stromboli smoke?"],"ch13-obsidian":["How did we get around the island — and what did it cost, agreed when?","Where was lunch, and what story did the table produce?","Did anyone jump off anything?"],"ch14-the-volcano-upstage":["Was Etna doing anything behind the stage?","What granita, in what order?","What was the last-night table like?"],"ch15-the-knights-city":["How long did we stand in front of the Beheading?","Did we make the noon gun or hear it from somewhere else?","What was the room like after ten nights afloat?"],"ch16-slow-malta":["What did Mdina sound like?","What did the dghajsa boatman talk about?","Did anyone jump at St Peter''s Pool?"],"ch17-the-crossing":["Was the crossing smooth, and did anyone regret breakfast?","Which driver quote won, and how was it found?","What was the 230 kilometres like from the back seat?"],"ch18-lunch-at-one":["Where did she take us?","Were the parents there — and what was that like?","Which dish did the table go quiet for?"],"ch19-gold-in-the-morning":["What did Claire say inside Monreale?","What came home from Ballarò?","Where was the last dinner, and what was the toast?"],"ch20-the-long-way-home":["Did the F bid land?","What was the lounge''s one contribution to the trip?","First thing said on the ground in Sydney?"]}');
INSERT OR IGNORE INTO journal_meta (id, json) VALUES ('v1', '{"title":"The Crossing","sub":"conditions remain grim","hero":"Twenty-one days, four countries, one attempted robbery, one unplanned city, the last berth on a small French ship, and a table in Palermo that could not be booked, only offered.","indexable":false,"threads":{"doctrine":"the plan is a doctrine, not an itinerary","screens":"how to read a room, a queue, a lanyard","trade-channel":"the best assets can''t be booked, only introduced","water":"arrival by water, swims with stories in them","drops":"one image, one question, filed by site","ledger":"every price and what it actually bought","hardship":"the family register. conditions remain grim."},"cast":["Michael & Claire — the leads","Le Dumont d’Urville — 92 staterooms, one of them ours","the three gentlemen of Gare du Nord — brief appearance, poor reviews","Aurora — Palermo. The table on the first of September was hers."]}');
INSERT OR IGNORE INTO journal_intel (id, json) VALUES ('v1', '{"doctrine":[{"n":1,"rule":"The hard deadline is a cliff. Plan to last-boat-minus-one; the final boat is the reserve. Avoid ruin, then optimise.","provenance":["ch01-gare-du-nord"],"status":"lived"},{"n":2,"rule":"Spend scarce hours on non-substitutable assets.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":3,"rule":"Highest-variance leg first, where the buffer is.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":4,"rule":"Capacity-capped early; elastic items last — they double as shock absorbers.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":5,"rule":"Pre-commit the switch criterion at the fork. Judge on behaviour, never timetables. One decision, no sunk-cost drift.","provenance":["ch01-gare-du-nord"],"status":"lived — the lanyard read as behaviour, not costume"}],"corollaries":[{"text":"best-version: never consume the degraded version of a peak experience — defer and rebook.","provenance":["ch03-fourteen-degrees"],"status":"lived — Mont Blanc, 17 Aug, \"I won''t watch cams\""},{"text":"the pré-plainte-online protocol: file the same evening, attach everything, close the loop.","provenance":["ch01-gare-du-nord"],"status":"lived"},{"text":"timetables are narrative, queues are behaviour · price agreed before boarding · said twice, echoed back, screenshot","provenance":[],"status":"aspirational — written before the trip caught up"}],"contacts":[{"name":"Virtu Ferries","ref":"10729224 / ETYWX","what":"Valletta→Pozzallo 31 Aug 07:30","status":"booked"},{"name":"1926 La Galerie","ref":"73521701309804","what":"Valletta premium suite","status":"booked"},{"name":"TGV Lyon→Nice","ref":"TKD3G6 / BL4P7Q / HPW6G9","what":"the 11:40, 18 Aug","status":"booked"},{"name":"Pozzallo drivers","ref":"quotes €280–380","what":"the 230km to Palermo","status":"open"}],"protocols":[{"name":"recap-echo-screenshot","steps":["price said twice","echoed back","screenshot"],"status":"aspirational — written before the trip caught up"}]}');
